cat << 'EOF' > patch.js
const fs = require('fs');
const content = fs.readFileSync('src/orchestration/chatOrchestrator.ts', 'utf8');
const newContent = content.replace(
/          if \(outcome\.usage\) \{\n            if \(totalUsage\) \{\n              totalUsage = \{\n                inputTokens: totalUsage\.inputTokens \+ outcome\.usage\.inputTokens,\n                outputTokens: totalUsage\.outputTokens \+ outcome\.usage\.outputTokens,\n                totalTokens: totalUsage\.totalTokens \+ outcome\.usage\.totalTokens,\n              \};\n            \} else \{\n              totalUsage = \{\.\.\.outcome\.usage\};\n            \}\n          \}/,
`          const roundUsage = outcome.usage;
          const previousUsage = totalUsage;

          if (roundUsage && !previousUsage) {
            totalUsage = {...roundUsage};
          }
          if (roundUsage && previousUsage) {
            totalUsage = {
              inputTokens: previousUsage.inputTokens + roundUsage.inputTokens,
              outputTokens: previousUsage.outputTokens + roundUsage.outputTokens,
              totalTokens: previousUsage.totalTokens + roundUsage.totalTokens,
            };
          }`
);
fs.writeFileSync('src/orchestration/chatOrchestrator.ts', newContent);
EOF
node patch.js

