cat << 'EOF' > patch3.cjs
const fs = require('fs');
let content = fs.readFileSync('src/orchestration/chatOrchestrator.test.ts', 'utf8');

const test1 = `  it('sums the usage of every round, not only the last', async () => {
    const usage1: UsageMetadata = {inputTokens: 11, outputTokens: 2, totalTokens: 13};
    const usage2: UsageMetadata = {inputTokens: 20, outputTokens: 3, totalTokens: 23};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, totalUsage) => {
        seen = totalUsage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: usage1}],
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn', usage: usage2},
        ],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual({inputTokens: 31, outputTokens: 5, totalTokens: 36});
  });

`;

const test2 = `  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });

`;

content = content.replace(test1, '');
content = content.replace(test2, '');
fs.writeFileSync('src/orchestration/chatOrchestrator.test.ts', content);
EOF
node patch3.cjs

